from fastapi import Depends, Security
from typing import Annotated

def test_frozen():
    def dep(): pass
    d = Depends(dependency=dep)
    try:
        d.dependency = lambda x: x
        print("Depends is NOT frozen")
        return False
    except Exception as e:
        print(f"Depends is frozen: {e}")

    def sec(): pass
    s = Security(dependency=sec, scopes=["admin"])
    try:
        s.scopes = ["user"]
        print("Security is NOT frozen")
        return False
    except Exception as e:
        print(f"Security is frozen: {e}")

    return True

if __name__ == "__main__":
    if test_frozen():
        print("All frozen tests passed!")
    else:
        print("Some frozen tests failed!")
        exit(1)
